var i=`1023-banh-mi-thit`;var t=`world-1023`;var r=`VN`;var n=`southeast-asia`;var s=4;var o=78;var g={en:`Banh Mi Thit`,ua:`Бан мі з м'ясом`};var l={en:`Banh Mi Thit is a dish from Vietnam prepared with pork loin, fish sauce, garlic, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used. Prepared liver sausage replaces traditional pork-liver pâté in this bánh mì.`,ua:`Бан мі з м'ясом, страва кухні країни В'єтнам, яку готують із таких продуктів: свиняча корейка, рибний соус, часник, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Готова ліверна ковбаса замінює традиційний печінковий паштет у бань мі.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`pork-loin`,700,`g`],[`fish-sauce`,30,`ml`],[`garlic`,4,`clove`],[`lemongrass`,22,`g`],[`white-granulated-sugar`,12,`g`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:20,i:[]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`cucumber`,220,`g`],[`carrot`,160,`g`],[`pickled-daikon`,130,`g`],[`cilantro`,30,`g`]]},{en:`Split each baguette, spread a thin layer of mayonnaise and the ready-to-eat liver sausage, then add fully cooked pork and crisp vegetables; serve fresh.`,ua:`Розріжте багети, намастіть тонким шаром майонезу та готової ліверної ковбаси, додайте повністю приготовану свинину й хрусткі овочі; подавайте свіжими.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`baguette`,4,`pcs`],[`mayonnaise`,120,`g`],[`liver-sausage`,120,`g`],[`serrano-pepper`,1,`pcs`]]}];var d={slug:i,id:t,country:`VN`,region:n,servings:4,minutes:78,title:g,text:l,steps:h};export{r as country,d as default,t as id,o as minutes,n as region,s as servings,i as slug,h as steps,l as text,g as title};